import os
import hashlib
import hmac
import unicodedata
import re
from pathlib import PurePosixPath

# Secure file serving system with path validation
SECRET = os.environ.get('HMAC_SECRET', os.urandom(32).hex())
BASE_DIR = '/srv/shared/documents'


def generate_access_token(username: str, allowed_path: str) -> str:
    """Generate HMAC-signed access token for a specific path."""
    msg = f"{username}:{allowed_path}".encode('utf-8')
    sig = hmac.new(SECRET.encode(), msg, hashlib.sha256).hexdigest()
    return f"{username}:{allowed_path}:{sig}"


def verify_access_token(token: str) -> tuple:
    """Verify token and return (username, allowed_path) or raise."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        raise ValueError("Invalid token format")
    msg_part, sig = parts
    expected = hmac.new(SECRET.encode(), msg_part.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, sig):
        raise ValueError("Invalid signature")
    user_path = msg_part.split(':', 1)
    if len(user_path) != 2:
        raise ValueError("Invalid token payload")
    return user_path[0], user_path[1]


def sanitize_path_component(component: str) -> str:
    """Remove dangerous characters from a single path component."""
    # Strip null bytes and control characters
    component = re.sub(r'[\x00-\x1f\x7f]', '', component)
    return component


def is_safe_path(requested_path: str, allowed_base: str) -> bool:
    """Check if requested_path is safely within allowed_base.

    Security: Validates path traversal attempts by checking
    that the resolved path starts with the allowed base.
    """
    # Reject obvious traversal attempts
    if '..' in requested_path:
        return False

    # Reject paths with backslashes (Windows-style)
    if '\\' in requested_path:
        return False

    # Normalize path separators and resolve
    clean_requested = str(PurePosixPath(requested_path))
    clean_base = str(PurePosixPath(allowed_base))

    # Ensure the requested path is under the allowed base
    if not clean_requested.startswith(clean_base):
        return False

    return True


def normalize_filename(filename: str) -> str:
    """Normalize Unicode in filename for consistent storage lookup.

    Uses NFKC normalization to handle equivalent Unicode representations.
    This ensures that files are found regardless of how the Unicode
    characters were encoded by the client.
    """
    return unicodedata.normalize('NFKC', filename)


def serve_file(token: str, requested_path: str) -> dict:
    """Main entry point: verify token and serve file if authorized.

    Security model:
    1. Verify HMAC signature on access token
    2. Validate requested path is within allowed directory
    3. Normalize filename for filesystem lookup
    4. Return file contents
    """
    # Step 1: Verify the access token
    try:
        username, allowed_path = verify_access_token(token)
    except ValueError as e:
        return {'status': 403, 'error': str(e)}

    # Step 2: Construct the full path
    full_allowed = os.path.join(BASE_DIR, allowed_path)
    full_requested = os.path.join(BASE_DIR, requested_path)

    # Step 3: Sanitize each component
    parts = requested_path.split('/')
    sanitized_parts = [sanitize_path_component(p) for p in parts]
    sanitized_path = '/'.join(sanitized_parts)

    # Step 4: Security check - is the path within bounds?
    if not is_safe_path(full_requested, full_allowed):
        return {'status': 403, 'error': 'Access denied: path outside allowed directory'}

    # Step 5: Normalize the filename for filesystem lookup
    # This handles Unicode equivalence (e.g., fi ligature -> fi)
    normalized_path = normalize_filename(sanitized_path)
    final_path = os.path.join(BASE_DIR, normalized_path)

    # Step 6: Serve the file
    if not os.path.isfile(final_path):
        return {'status': 404, 'error': 'File not found'}

    try:
        with open(final_path, 'r') as f:
            content = f.read()
        return {'status': 200, 'content': content, 'user': username}
    except (IOError, OSError) as e:
        return {'status': 500, 'error': 'Internal error'}


def handle_request(method: str, path: str, headers: dict) -> dict:
    """HTTP request handler."""
    if method != 'GET':
        return {'status': 405, 'error': 'Method not allowed'}

    token = headers.get('Authorization', '').replace('Bearer ', '')
    if not token:
        return {'status': 401, 'error': 'No token provided'}

    # Extract the file path from the URL
    if not path.startswith('/files/'):
        return {'status': 404, 'error': 'Not found'}

    file_path = path[7:]  # Remove '/files/' prefix

    return serve_file(token, file_path)
